<template>
 <section class="enrollment-portal" aria-label="AuricWell portal documents">
  <header><img src="/auricwell/mark.svg" alt="" /><div><p>AuricWell · {{ catalog?.branding?.name||'Client medical file' }}</p><h3>Portal documents</h3><p>Start an enrollment document, share it for completion, and follow its signatures in the client’s record.</p></div><button :disabled="loading||busy" @click="load">Refresh</button></header>
  <p v-if="notice" role="status">{{ notice }}</p>
  <template v-if="selectedRecord"><button @click="closeRecord">← All portal documents</button><SafetyPlansPanel ref="documentPanel" :key="selectedRecord" :client-id="clientId" :agency-id="agencyId" :initial-record-id="selectedRecord" record-only /></template>
  <template v-else>
   <div class="packet-options"><label>Setting<select v-model="context.channel"><option value="office">Office / virtual</option><option value="school">School</option></select></label><label>Completed by<select v-model="context.audience"><option value="self">Individual enrolling themselves</option><option value="guardian">Guardian for a dependent</option></select></label><label>Service<select v-model="context.service"><option value="counseling">Counseling</option><option value="tutoring">Tutoring</option></select></label><label>Language<select v-model="context.locale"><option value="en">English</option><option value="es">Spanish</option></select></label></div>
<p v-if="error" role="alert">{{ error }}</p><p v-if="loading" role="status">Loading documents…</p>
   <div v-if="!loading" class="assignment-toolbar"><div><strong>Assign documents &amp; forms</strong><p>Select saved documents or new enrollment forms, then share the selection together.</p></div><button type="button" :disabled="!selectedDocuments.length||selectedDocuments.length>30" @click="assignSelection">Assign {{ selectedDocuments.length?selectedDocuments.length:'selected' }} to portal</button><button v-if="selectedDocuments.length" type="button" @click="selectedSaved=[];selectedSources=[]">Clear selection</button></div>
   <section class="saved-documents"><h4>Saved and shared documents</h4><label class="search">Search documents<input v-model="search" type="search" placeholder="Document name or type…" /></label><p v-if="!loading&&!filteredRecords.length">No saved documents match.</p><div v-if="filteredRecords.length" class="record-table"><table><thead><tr><th>Select</th><th>Document</th><th>Portal</th><th>Signatures</th><th>Review</th><th></th></tr></thead><tbody><tr v-for="r in filteredRecords" :key="r.id"><td><input v-model="selectedSaved" type="checkbox" :value="r.id" :disabled="!!r.revoked" :aria-label="`Select ${r.documentName||r.title}`" /></td><td><strong>{{ r.documentName||r.title }}</strong><small>{{ r.title }} · Version {{ r.version }}</small></td><td>{{ r.sharedCount?`${r.sharedCount} shared`:'Not shared' }}</td><td>{{ r.signedCount||0 }} signed<span v-if="r.pendingSignatures"> · {{ r.pendingSignatures }} pending</span></td><td>{{ r.reviewStatus==='pending'?'Awaiting review':r.reviewStatus==='reviewed'?'Reviewed':'—' }}</td><td><button @click="openRecord(r)">{{ assignmentOnly?'Assign':'Open / share' }}</button></td></tr></tbody></table></div></section>
   <section v-if="!loading" class="document-picker"><div class="picker-heading"><h4>Enrollment forms</h4><button type="button" :disabled="!catalog?.documents?.length" @click="selectAllForms">Select all enrollment forms</button></div><p>Select forms to send directly for completion, or open one to prepare it first.</p><div class="document-cards"><article v-for="d in catalog?.documents||[]" :key="d.key" class="document-card"><label><input v-model="selectedSources" type="checkbox" :value="d.key" :aria-label="`Select ${d.title}`" /><strong>{{ d.title }}</strong></label><button v-if="!assignmentOnly" type="button" :disabled="busy" @click="startDocument(d)">Open form →</button></article></div></section>
  </template>
  <PortalDocumentAssignmentDialog v-if="assignmentOpen" :client-id="clientId" :agency-id="agencyId" :documents="assignmentDocuments" :recipients="catalog?.recipients||[]" :context="context" @close="assignmentOpen=false" @assigned="assigned" />
 </section>
</template>
<script setup>
import {computed,ref,watch,onBeforeUnmount} from 'vue';
import api from '../../services/api';
import SafetyPlansPanel from '../safetyPlans/SafetyPlansPanel.vue';
import PortalDocumentAssignmentDialog from './PortalDocumentAssignmentDialog.vue';
const props=defineProps({clientId:{type:Number,required:true},agencyId:Number,assignmentOnly:Boolean});
const context=ref({channel:'office',audience:'guardian',service:'counseling',locale:'en'});
const documentPanel=ref(null);
const selectedSaved=ref([]),selectedSources=ref([]),assignmentOpen=ref(false),assignmentDocuments=ref([]),notice=ref('');
const selectedDocuments=computed(()=>[...records.value.filter(r=>selectedSaved.value.includes(r.id)).map(r=>({recordId:r.id,version:r.version,title:r.documentName||r.title})),...(catalog.value?.documents||[]).filter(d=>selectedSources.value.includes(d.key)).map(d=>({foundationKey:d.key,title:d.title}))]);
function openRecord(record){if(props.assignmentOnly){assignmentDocuments.value=[{recordId:record.id,version:record.version,title:record.documentName||record.title}];assignmentOpen.value=true;}else selectedRecord.value=record.id;}
function assignSelection(){if(!selectedDocuments.value.length)return;assignmentDocuments.value=selectedDocuments.value.map(d=>({...d}));assignmentOpen.value=true;}
function selectAllForms(){selectedSources.value=(catalog.value?.documents||[]).slice(0,30).map(d=>d.key);}
async function assigned(result){assignmentOpen.value=false;selectedSaved.value=[];selectedSources.value=[];notice.value=result.assignedCount?`${result.assignedCount} ${result.assignedCount===1?'item is':'items are'} now in ${result.recipientName||'the recipient'}’s portal. Notification delivery has not been confirmed.`:'These documents are already assigned to this portal.';await load();}
const catalog=ref(null),records=ref([]),selectedRecord=ref(null),loading=ref(false),busy=ref(false),error=ref(''),search=ref('');let generation=0;
const filteredRecords=computed(()=>records.value.filter(r=>`${r.documentName||''} ${r.title||''}`.toLowerCase().includes(search.value.trim().toLowerCase())));
async function load(){const g=++generation;loading.value=true;catalog.value=null;records.value=[];selectedSaved.value=[];selectedSources.value=[];error.value='';try{const [c,r]=await Promise.all([api.get(`/enrollment-portal/clients/${props.clientId}/catalog`,{params:{...context.value,agencyId:props.agencyId}}),api.get('/clinical-forms',{params:{clientId:props.clientId}})]);if(g!==generation)return;catalog.value=c.data;records.value=r.data.plans||[];}catch(e){if(g===generation)error.value=e.response?.data?.error?.message||'Portal documents could not be loaded. Please try again.';}finally{if(g===generation)loading.value=false;}}
async function startDocument(document){if(busy.value||!catalog.value)return;const g=generation;busy.value=true;error.value='';try{const {data}=await api.post(`/enrollment-portal/clients/${props.clientId}/documents`,{agencyId:props.agencyId,foundationKey:document.key,context:{...context.value},data:{documentName:document.title,personLabel:catalog.value.client.name,planDate:new Date().toLocaleDateString('en-CA')}});if(g===generation)selectedRecord.value=data.id;}catch(e){if(g===generation)error.value=e.response?.data?.error?.message||'The document was not saved. Please try again.';}finally{if(g===generation)busy.value=false;}}
function prepareToLeave(){if(busy.value||assignmentOpen.value)return false;return documentPanel.value?.confirmDiscard?.()!==false;}
function closeRecord(){if(!prepareToLeave())return;selectedRecord.value=null;load();}
defineExpose({prepareToLeave});
watch(()=>[props.clientId,props.agencyId,context.value.channel,context.value.audience,context.value.service,context.value.locale],()=>{selectedRecord.value=null;assignmentOpen.value=false;notice.value='';busy.value=false;load();},{immediate:true});
onBeforeUnmount(()=>{generation++;catalog.value=null;records.value=[];});
</script>
<style scoped>
.enrollment-portal{color:#203d36;margin:18px 0;border:1px solid #d9e5df;border-radius:14px;padding:22px;background:#fff}.enrollment-portal header{display:flex;gap:14px;align-items:center;margin-bottom:20px}.enrollment-portal header img{width:38px;height:38px}.enrollment-portal header div{flex:1}.enrollment-portal h3{font-size:23px;margin:4px 0}.enrollment-portal h4{font-size:17px;margin:12px 0}.enrollment-portal p{font-size:13px;line-height:1.65;margin:4px 0;color:#587067}.packet-options{display:flex;flex-wrap:wrap;gap:14px;padding:16px 0;border-top:1px solid #e4ebe7}.enrollment-portal label{display:grid;gap:7px;font-size:12px}.enrollment-portal input,.enrollment-portal select,.enrollment-portal button{font:inherit;padding:10px 12px;border:1px solid #b7cbbf;border-radius:7px;background:#fff;color:#234d40}.enrollment-portal button{cursor:pointer}.enrollment-portal button:disabled{opacity:.5;cursor:wait}.document-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px;margin:14px 0 24px}.document-cards button{display:grid;grid-template-columns:25px 1fr;gap:10px;text-align:left}.document-cards button small{grid-column:2;color:#537969}.document-cards button span{font-size:24px}.search{max-width:400px;margin:10px 0}.record-table{overflow-x:auto}.record-table table{width:100%;border-collapse:collapse;font-size:13px}.record-table th,.record-table td{text-align:left;padding:12px;border-bottom:1px solid #e1e9e5}.record-table small{display:block;color:#60766d;margin-top:5px}[role=alert]{background:#fff0eb;color:#8d3225;padding:12px;border-radius:7px}@media(max-width:650px){.enrollment-portal{padding:14px}.enrollment-portal header{align-items:flex-start}.packet-options>*{flex:1;min-width:180px}}
.assignment-toolbar{display:flex;align-items:center;flex-wrap:wrap;gap:12px;margin:14px 0;padding:16px;border-radius:10px;background:#eef6f0}.assignment-toolbar>div{flex:1;min-width:220px}.picker-heading{display:flex;justify-content:space-between;align-items:center;gap:12px}.document-card{display:flex;flex-direction:column;justify-content:space-between;gap:18px;border:1px solid #d9e5df;border-radius:10px;padding:16px}.document-card label{display:flex;align-items:flex-start;gap:10px;font-size:14px}.document-card input,.record-table input{width:18px;height:18px;flex-shrink:0}.document-cards .document-card button{display:block;text-align:left}.enrollment-portal [role=status]{padding:12px;background:#edf6e9;border-radius:7px}
</style>
